    if(!color){canvas?.remove();host._designPaintSignature='';return;}
    if(!image.naturalWidth||!image.naturalHeight)return;
    const signature=[image.currentSrc||image.src,image.naturalWidth,image.naturalHeight,color,host.dataset.designColorOpacity??100].join(':');
    if(!canvas){canvas=document.createElement('canvas');canvas.className='design-color-overlay';canvas.setAttribute('aria-hidden','true');host.appendChild(canvas);}
    if(host._designPaintSignature!==signature){const scale=Math.min(1,1200/Math.max(image.naturalWidth,image.naturalHeight));canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));const ctx=canvas.getContext('2d');try{ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);ctx.globalCompositeOperation='source-atop';ctx.globalAlpha=Number(host.dataset.designColorOpacity??100)/100;ctx.fillStyle=color;ctx.fillRect(0,0,canvas.width,canvas.height);ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';host._designPaintSignature=signature;}catch{image.style.opacity='1';canvas.remove();return;}}
