      const unit=productionDesignUnitCost(x,d),mat=designPrintMaterial({...d,print_material_type:type}),extraWaste=productionDesignHasPrintedOrigin(x,d)?0:waste;if(unit!==null){const line=Math.ceil(unit*Math.max(1,Number(x.quantity)||1)*(1+extraWaste/100)/100)*100;printCost+=line;lines.push(`${d.name}: ${money(line)} · ${Number(x.widthCm).toLocaleString('es-AR',{maximumFractionDigits:2})} × ${Number(x.heightCm).toLocaleString('es-AR',{maximumFractionDigits:2})} cm${extraWaste?` · incluye ${extraWaste}% de desperdicio`:''}`);if(!mat)warnings.push(`Costo de ${d.name} tomado de la plancha; sin stock DTF cargado.`);continue;}
