  function purchaseQuantitySummary(items=[]){
    const groups=new Map(),labels={shirt:['remera','remeras'],hoodie:['buzo','buzos'],chomba:['chomba','chombas'],cap:['gorra','gorras'],mug:['taza','tazas'],glass:['vaso','vasos'],thermos:['termo','termos'],bag:['bolso','bolsos']};
    for(const item of items){const type=item.materialType||item.material_type||'other',quantity=Number(item.quantity)||0;if(quantity<=0)continue;const fit=materialIsGarment(type)?String(item.fit||'').trim():'',key=JSON.stringify([type,fit,item.unit||'']);const group=groups.get(key)||{type,fit,quantity:0,unit:item.unit};group.quantity+=quantity;groups.set(key,group);}
    return [...groups.values()].map(g=>{const count=g.quantity.toLocaleString('es-AR',{maximumFractionDigits:3});if(materialIsDtf(g.type))return `${count} m de ${materialTypeLabel(g.type)}`;const [one,many]=labels[g.type]||[materialTypeLabel(g.type).toLowerCase(),materialTypeLabel(g.type).toLowerCase()];const cut=g.fit?photoFit(g.fit):'';const suffix=cut==='oversize'?'over':cut==='clasico'?(g.quantity===1?'clásica':'clásicas'):g.fit;return `${count} ${g.quantity===1?one:many}${suffix?' '+suffix:''}`;}).join(' · ');
  }
